export type PhotoSlug = keyof typeof photoMeta;

/**
 * Описание всегда обязательно: страница почти целиком состоит из фотографий,
 * и без alt она непроходима для скринридера.
 */
export function photo(slug: PhotoSlug, alt: string): ProductImage {
  const meta = photoMeta[slug];
  return {
    url: `/photo/${slug}.jpg`,
    alt,
    width: meta.width,
    height: meta.height,
    blurDataURL: meta.blurDataURL,
  };
}

/** Есть ли кадр с таким слагом — для слагов, собранных из данных (cat-*) */
export function hasPhoto(slug: string): slug is PhotoSlug {
  return Object.prototype.hasOwnProperty.call(photoMeta, slug);
}
